def maxRemainderScore(nums, k, p):
    n = len(nums)
    pre = [0] * (n + 1)
    for i, x in enumerate(nums):
        pre[i + 1] = (pre[i] + x) % p
    prev = [-1] * (n + 1)
    prev[0] = 0
    for j in range(1, k + 1):
        cur = [-1] * (n + 1)
        best = [-1] * p
        for i in range(j, n + 1):
            t = i - 1
            if prev[t] > best[pre[t]]:
                best[pre[t]] = prev[t]
            c = pre[i]
            m = -1
            for r in range(p):
                b = best[r]
                if b >= 0:
                    v = b + (c - r) % p
                    if v > m:
                        m = v
            cur[i] = m
        prev = cur
    return prev[n]
